CREATE INDEX IF NOT EXISTS items_fts ON items USING gin (fts);
ALTER TABLE comments ADD COLUMN IF NOT EXISTS fts tsvector GENERATED ALWAYS AS (setweight(to_tsvector('english'::regconfig, coalesce(body, '')), 'D')) STORED;
