INSERT INTO item_plans_rev (id, rev) VALUES (1, 0) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION trg_item_plans_rev() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('autocraft.item_plans_rev', true) IS DISTINCT FROM '1' THEN
    PERFORM set_config('autocraft.item_plans_rev', '1', true);
    UPDATE item_plans_rev SET rev = rev + 1;
  END IF;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER item_plans_rev_i AFTER INSERT ON item_plans FOR EACH ROW EXECUTE FUNCTION trg_item_plans_rev();
CREATE OR REPLACE TRIGGER item_plans_rev_u AFTER UPDATE ON item_plans FOR EACH ROW EXECUTE FUNCTION trg_item_plans_rev();
