  repo text COLLATE "C" NOT NULL,
  number bigint NOT NULL,
  decision_id text COLLATE "C" NOT NULL,
  PRIMARY KEY (repo, number, decision_id)
);
CREATE OR REPLACE FUNCTION trg_decision_items_ins() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.number IS NULL AND (CASE WHEN json_valid(NEW.items) THEN json_typeof(NEW.items::json) = 'array' ELSE false END) THEN
    INSERT INTO decision_items (repo, number, decision_id)
      SELECT j ->> 'repo', (j ->> 'number')::bigint, NEW.id FROM json_array_elements(NEW.items::json) j
      WHERE json_typeof(j) = 'object' AND json_typeof(j -> 'repo') = 'string' AND json_typeof(j -> 'number') = 'number'
        AND (j ->> 'number') ~ '^-?[0-9]+$'
      ON CONFLICT DO NOTHING;
  END IF;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER decision_items_ins AFTER INSERT ON decisions FOR EACH ROW EXECUTE FUNCTION trg_decision_items_ins();
CREATE OR REPLACE FUNCTION trg_decision_items_upd() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  DELETE FROM decision_items WHERE decision_id = NEW.id;
  IF NEW.number IS NULL AND (CASE WHEN json_valid(NEW.items) THEN json_typeof(NEW.items::json) = 'array' ELSE false END) THEN
    INSERT INTO decision_items (repo, number, decision_id)
      SELECT j ->> 'repo', (j ->> 'number')::bigint, NEW.id FROM json_array_elements(NEW.items::json) j
      WHERE json_typeof(j) = 'object' AND json_typeof(j -> 'repo') = 'string' AND json_typeof(j -> 'number') = 'number'
        AND (j ->> 'number') ~ '^-?[0-9]+$'
      ON CONFLICT DO NOTHING;
  END IF;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER decision_items_upd AFTER UPDATE ON decisions FOR EACH ROW
  WHEN (OLD.items IS DISTINCT FROM NEW.items OR OLD.number IS DISTINCT FROM NEW.number) EXECUTE FUNCTION trg_decision_items_upd();
CREATE OR REPLACE FUNCTION trg_decision_items_del() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  DELETE FROM decision_items WHERE decision_id = OLD.id;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER decision_items_del AFTER DELETE ON decisions FOR EACH ROW EXECUTE FUNCTION trg_decision_items_del();
