CREATE OR REPLACE FUNCTION trg_jobs_ever() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO ever_tracked_repos (name)
    VALUES (CASE WHEN NEW.repo LIKE '(security):%' THEN substr(NEW.repo, 12) ELSE NEW.repo END) ON CONFLICT DO NOTHING;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER jobs_ever AFTER INSERT ON jobs FOR EACH ROW WHEN (NEW.repo IS NOT NULL) EXECUTE FUNCTION trg_jobs_ever();
CREATE OR REPLACE FUNCTION trg_build_tasks_ever() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO ever_tracked_repos (name)
    VALUES (CASE WHEN NEW.repo LIKE '(security):%' THEN substr(NEW.repo, 12) ELSE NEW.repo END) ON CONFLICT DO NOTHING;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER build_tasks_ever AFTER INSERT ON build_tasks FOR EACH ROW WHEN (NEW.repo IS NOT NULL) EXECUTE FUNCTION trg_build_tasks_ever();
CREATE OR REPLACE FUNCTION trg_agent_run_items_ever() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO ever_tracked_repos (name)
    VALUES (CASE WHEN NEW.repo LIKE '(security):%' THEN substr(NEW.repo, 12) ELSE NEW.repo END) ON CONFLICT DO NOTHING;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER agent_run_items_ever AFTER INSERT ON agent_run_items FOR EACH ROW WHEN (NEW.repo IS NOT NULL) EXECUTE FUNCTION trg_agent_run_items_ever();
