  run text COLLATE "C" NOT NULL,
  repo text COLLATE "C" NOT NULL,
  number bigint NOT NULL,
  status text COLLATE "C" NOT NULL,
  label text COLLATE "C",
  source text COLLATE "C",
  top double precision,
  jev_label text COLLATE "C",
  haiku_label text COLLATE "C",
  flags text COLLATE "C" NOT NULL,
  security bigint NOT NULL,
  needs_decision bigint NOT NULL,
  referee_label text COLLATE "C",
  referee_sure bigint,
  referee_reason text COLLATE "C",
  referee_final bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (run, repo, number)
);
