CREATE TABLE IF NOT EXISTS item_settled_dirty (
  run_id text COLLATE "C" NOT NULL,
  repo text COLLATE "C" NOT NULL,
  number bigint NOT NULL,
  n bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (run_id, repo, number)
);
CREATE OR REPLACE FUNCTION trg_classifications_settled() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP <> 'DELETE' THEN
    INSERT INTO item_settled_dirty (run_id, repo, number) VALUES (NEW.run_id, NEW.repo, NEW.number)
      ON CONFLICT (run_id, repo, number) DO UPDATE SET n = item_settled_dirty.n + 1;
  END IF;
  IF TG_OP = 'DELETE' THEN
    INSERT INTO item_settled_dirty (run_id, repo, number) VALUES (OLD.run_id, OLD.repo, OLD.number)
      ON CONFLICT (run_id, repo, number) DO UPDATE SET n = item_settled_dirty.n + 1;
  ELSIF TG_OP = 'UPDATE' THEN
    IF (OLD.run_id, OLD.repo, OLD.number) IS DISTINCT FROM (NEW.run_id, NEW.repo, NEW.number) THEN
      INSERT INTO item_settled_dirty (run_id, repo, number) VALUES (OLD.run_id, OLD.repo, OLD.number)
      ON CONFLICT (run_id, repo, number) DO UPDATE SET n = item_settled_dirty.n + 1;
    END IF;
  END IF;
  RETURN NULL;
END $$;
CREATE OR REPLACE TRIGGER classifications_settled_i AFTER INSERT ON classifications FOR EACH ROW EXECUTE FUNCTION trg_classifications_settled();
CREATE OR REPLACE TRIGGER classifications_settled_u AFTER UPDATE ON classifications FOR EACH ROW EXECUTE FUNCTION trg_classifications_settled();
CREATE OR REPLACE TRIGGER classifications_settled_d AFTER DELETE ON classifications FOR EACH ROW EXECUTE FUNCTION trg_classifications_settled();
