CREATE INDEX IF NOT EXISTS remote_calls_leased ON remote_calls (token_id, claim_id, user_login, heartbeat_at, leased_at, started_at, timeout_ms) WHERE state = 'leased';
CREATE INDEX IF NOT EXISTS remote_calls_leased_own ON remote_calls (user_login, token_id) WHERE state = 'leased' AND own_lane = 1;
CREATE UNIQUE INDEX IF NOT EXISTS conversation_cards_choice_live ON conversation_cards (choice_id) WHERE choice_id IS NOT NULL AND state IN ('proposed', 'running', 'done');
CREATE OR REPLACE FUNCTION trg_decisions_answered_role() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.answered_role := (SELECT role FROM access WHERE login = NEW.answered_by::citext);
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER decisions_answered_role BEFORE UPDATE OF answered_by ON decisions FOR EACH ROW EXECUTE FUNCTION trg_decisions_answered_role();
CREATE INDEX IF NOT EXISTS comments_mention ON comments (created_at) WHERE mentions_pipeline = 1;
CREATE INDEX IF NOT EXISTS comments_author_item ON comments (author, repo, number);
CREATE INDEX IF NOT EXISTS dupe_carries_item ON dupe_carries (repo, number);
CREATE INDEX IF NOT EXISTS classifications_alone ON classifications (at) WHERE classifier = 'haiku' AND input_hash IS NOT NULL;
CREATE INDEX IF NOT EXISTS jobs_step_repo ON jobs (step, repo, id);
CREATE INDEX IF NOT EXISTS items_class ON items (state, repo, number, class_scheme, class_hash);
CREATE INDEX IF NOT EXISTS items_embed ON items (repo, number, embed_hash);
CREATE INDEX IF NOT EXISTS items_embed_missing ON items (repo, number) WHERE embed_hash IS NULL;
CREATE INDEX IF NOT EXISTS items_closing ON items (repo, number, closing_issues) WHERE kind = 'pr' AND closing_issues IS NOT NULL AND closing_issues <> '[]';
CREATE OR REPLACE FUNCTION trg_items_hash_stale() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.embed_hash := NULL;
  NEW.class_hash := NULL;
  NEW.class_scheme := NULL;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER items_hash_stale BEFORE UPDATE OF title, body, additions, deletions, changed_files, author_association, kind ON items FOR EACH ROW
  WHEN (NEW.embed_hash IS NOT DISTINCT FROM OLD.embed_hash AND NEW.class_hash IS NOT DISTINCT FROM OLD.class_hash AND NEW.class_scheme IS NOT DISTINCT FROM OLD.class_scheme
    AND (OLD.title IS DISTINCT FROM NEW.title OR OLD.body IS DISTINCT FROM NEW.body OR OLD.additions IS DISTINCT FROM NEW.additions
      OR OLD.deletions IS DISTINCT FROM NEW.deletions OR OLD.changed_files IS DISTINCT FROM NEW.changed_files
      OR OLD.author_association IS DISTINCT FROM NEW.author_association OR OLD.kind IS DISTINCT FROM NEW.kind))
  EXECUTE FUNCTION trg_items_hash_stale();
CREATE OR REPLACE FUNCTION trg_items_text_refs_stale() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.text_refs := NULL;
  RETURN NEW;
END $$;
CREATE OR REPLACE TRIGGER items_text_refs_stale BEFORE UPDATE OF title, body ON items FOR EACH ROW
  WHEN (NEW.text_refs IS NOT NULL AND NEW.text_refs IS NOT DISTINCT FROM OLD.text_refs AND (OLD.title IS DISTINCT FROM NEW.title OR OLD.body IS DISTINCT FROM NEW.body))
  EXECUTE FUNCTION trg_items_text_refs_stale();
DROP VIEW IF EXISTS final_reviews;
CREATE VIEW final_reviews AS SELECT repo, number, head_oid, run_id, at, model, verdict, reason, fixes, risks, sure, mode, base_head, seen_at, disc_hash FROM opus_reviews WHERE verdict IS NOT NULL;
